/// <summary>
/// PricingAttribute of table <c>SalesTable</c> field Port
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::SalesTable, UPSPricingAttributeSourceLevel::Header)]
internal class UPSPricingAttributeSalesTablePort extends UPSPricingAttributeSalesTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(SalesTable, Port);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);
    SalesTable salesTable;
    while select Port from salesTable
        group by Port
    {
        ret.add(salesTable.Port);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(SalesTable, Port));
    qbr.value(queryValue(_value));
}
